cpp.setup:
auto* anchor = new fluent::basicinput::Button(QStringLiteral("Reset toolbar"), %PARENT%);
anchor->setFixedSize(136, 32);
anchor->move(162, 174);
anchor->show();
auto* control = new fluent::dialogs_flyouts::Flyout(%PARENT%);
control->setAnimationEnabled(false);
control->setAnchor(anchor);
control->setLightDismissConsumesPress(true);
auto* layout = new QVBoxLayout(control);
layout->setContentsMargins(20, 18, 20, 18);
layout->setSpacing(6);
auto* heading = new fluent::textfields::Label(QStringLiteral("Reset layout?"), control);
heading->setFluentTypography(Typography::FontRole::BodyStrong);
layout->addWidget(heading);
auto* body = new fluent::textfields::Label(QStringLiteral("Restore toolbar items to defaults."), control);
body->setWordWrap(true);
body->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
layout->addWidget(body);
auto* action = new fluent::basicinput::Button(QStringLiteral("Reset now"), control);
action->setFluentStyle(fluent::basicinput::Button::Accent);
layout->addWidget(action, 0, Qt::AlignLeft);
control->setMinimumSize(256, 104);
QObject::connect(action, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::Flyout::close);
QObject::connect(anchor, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::Flyout::open);
